+				transaction, selectivity);
+
+			X.RDB$INDEX_ID = idx.idx_id + 1;
+		}
+		END_STORE
+
+		if (index->ini_idx_flags & idx_unique)
+		{
+			STORE(REQUEST_HANDLE handle3 TRANSACTION_HANDLE transaction)
+				RC IN RDB$RELATION_CONSTRAINTS
