+				strcpy(RC.RDB$CONSTRAINT_TYPE, UNIQUE_CNSTRT);
+				strcpy(RC.RDB$DEFERRABLE, "NO");
+				strcpy(RC.RDB$INITIALLY_DEFERRED, "NO");
+			}
+			END_STORE
+		}
+	}
